import Foundation
import XCTest
@testable import bIDE

final class MultiSheetXLSXTests: XCTestCase {
    private let workbookBase64 = """

"""

    func testInventoryAndRegionsIgnoreStyledEmptyCellsAndRows() throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("bide-xlsx-regression-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: root) }

        let workbookURL = root.appendingPathComponent("bIDE-Phase2-Test-MultiSheet.xlsx")
        let workbookData = try XCTUnwrap(Data(base64Encoded: workbookBase64, options: [.ignoreUnknownCharacters]))
        try workbookData.write(to: workbookURL, options: .atomic)

        let tables = try DatasetParser.parse(url: workbookURL, format: .xlsx)
        XCTAssertEqual(tables.count, 2)

        let inventory = try XCTUnwrap(tables.first(where: { $0.sourceSheetName == "Inventory" }))
        XCTAssertEqual(inventory.columns.count, 5)
        XCTAssertEqual(inventory.rows.count, 6)
        XCTAssertEqual(inventory.columns.map(\.name), ["sku", "product", "category", "quantity", "unit_price"])
        XCTAssertEqual(inventory.rows.first?[0], "SKU-001")
        XCTAssertEqual(inventory.rows.last?[0], "SKU-006")

        let regions = try XCTUnwrap(tables.first(where: { $0.sourceSheetName == "Regions" }))
        XCTAssertEqual(regions.columns.count, 3)
        XCTAssertEqual(regions.rows.count, 3)
        XCTAssertEqual(regions.columns.map(\.name), ["region_id", "region_name", "manager"])
        XCTAssertEqual(regions.rows.first?[0], "R01")
        XCTAssertEqual(regions.rows.last?[0], "R03")
    }
}
